package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** The date to defer the claim until. Publishes it with the user deferring it. */
public class ValidateDefer {
    public void validate(@RequestBody DeferRequest request, Out<DeferUntil> until, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String text = request == null || request.until() == null ? "" : request.until().trim();
        try {
            until.set(new DeferUntil(LocalDate.parse(text)));
        } catch (DateTimeParseException e) {
            throw new BadRequestException("Enter the date to defer until as yyyy-mm-dd");
        }
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;

/** Defers an OPEN claim until a date after the sheet's today; any other status, or a date not after today, is refused. */
public class ApplyDefer {
    public void apply(@Val Claim claim, @Val DeferUntil until, ClaimRepository repository, SheetRepository sheets)
            throws BadRequestException {
        if (claim.getStatus() != ClaimStatus.OPEN) {
            throw new BadRequestException("Only an OPEN claim is deferred; this one is " + claim.getStatus());
        }
        if (!until.date().isAfter(sheets.today(claim.getSheetId()))) {
            throw new BadRequestException("A claim is deferred to a date after the sheet's today");
        }
        claim.setDeferredUntil(until.date());
        if (!repository.defer(claim)) {
            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

/** CLAIM_DEFERRED, naming the claim, then the date it is deferred until. */
public class RecordClaimDeferred {
    public void record(@Val Claim claim, @Val ChangedBy by, PersonRepository people, Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.record(ClaimAudit.line("CLAIM_DEFERRED", claim, by, person == null ? "" : person.getName())
                + " until=" + claim.getDeferredUntil());
    }
}
package net.officefloor.hq.app.claim;

/** The date (yyyy-mm-dd) an OPEN claim is deferred until, and the signed-in user (`by`) deferring it. */
public record DeferRequest(String until, String by) {
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;

/** The date a claim is to be deferred until. */
public record DeferUntil(LocalDate date) {
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@Val SheetResponse sheet, @PathVariable("claimId") String claimId,
            ClaimRepository repository, Out<Claim> claim) throws BadRequestException {
        Claim found = null;
        try {
            found = repository.find(sheet.id(), Long.parseLong(claimId));
        } catch (NumberFormatException e) {
            // not an id: no such claim
        }
        if (found == null) {
            throw new BadRequestException("No such claim on this sheet");
        }
        claim.set(found);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithClaim {
    public void respond(@Val Claim claim, SheetRepository sheets, ObjectResponse<ClaimResponse> response) {
        response.send(ClaimResponse.from(claim, java.util.List.of(), sheets.today(claim.getSheetId())));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** The user adding a proof to the claim. */
public class ValidateProof {
    public void validate(@RequestBody ProofRequest request, Out<ChangedBy> changedBy) throws BadRequestException {
        changedBy.set(ChangedBy.of(request == null ? null : request.by()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Val;

/** Raises the claim's proofs count by one; a SETTLED or VOID claim is refused. */
public class ApplyProof {
    public void apply(@Val Claim claim, ClaimRepository repository) throws BadRequestException {
        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
            throw new BadRequestException("A " + claim.getStatus() + " claim takes no more proofs");
        }
        if (!repository.addProof(claim)) {
            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

/** CLAIM_PROOF_ADDED, naming the claim, then its proofs count now. */
public class RecordClaimProofAdded {
    public void record(@Val Claim claim, @Val ChangedBy by, PersonRepository people, Audit audit) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        audit.record(ClaimAudit.line("CLAIM_PROOF_ADDED", claim, by, person == null ? "" : person.getName())
                + " proofs=" + claim.getProofs());
    }
}
package net.officefloor.hq.app.claim;

/** The signed-in user (`by`) adding a proof to a claim. */
public record ProofRequest(String by) {
}

