1	import { useIsMutating, useMutation, useQueryClient } from '@tanstack/react-query';
2	import { useEffect, useState } from 'react';
3	import { postJson, putJson } from '../../api/http';
4	import { ClaimCells } from '../../slots/defs/claimRow';
5	import { usePeople } from '../people/people.slot';
6	import { periodOn, usePeriods } from '../periods/periods.slot';
7	import { useRoles } from '../access/useAccess';
8	import { useUser } from '../session/useSession';
9	import { HttpError } from '../../api/http';
10	import { claimLockKey, claimSaveKey, claimsKey, useEditingClaim, type Claim, type ClaimStatus } from './useClaims';
11	
12	// `review`: a steward's approve (to SETTLED) or reject (back to OPEN, with a reason) of a PENDING claim.
13	type Change = { status: ClaimStatus; review?: boolean; reason?: string };
14	
15	const ACTIONS: Array<{ action: string; change: Change; label: string }> = [
16	  { action: 'open', change: { status: 'OPEN' }, label: 'Open' },
17	  { action: 'settle', change: { status: 'SETTLED' }, label: 'Settle' },
18	  { action: 'void', change: { status: 'VOID' }, label: 'Void' },
19	  { action: 'approve', change: { status: 'SETTLED', review: true }, label: 'Approve' },
20	];
21	
22	// A claim's number and status, the buttons that open, settle, void, approve or reject it, and a steward's move of a DRAFT,
23	// OPEN or PENDING claim to another person (listed then as that person's newest claim). A change its status does not
24	// allow, a settle or approve by the user who opened the claim, or an approve or reject by a non-steward, is refused by the
25	// server, and the refusal shows on the claim until its next action (only the last action's error shows). A clerk's settle above the clerk limit leaves it PENDING.
26	// A steward may void a SETTLED claim within 7 days of its settlement (not in a closed period): its frozen due still shows but
27	// counts in no total.
28	// An OPEN claim can be deferred to a date after the sheet's today (not in a closed period): until then it counts in no
29	// total, is not overdue and cannot be settled; whether it is deferred, and until when, shows on the claim.
30	// A claim not SETTLED or VOID takes a proof, raising its proofs count by one; one whose due is above the proof threshold
31	// in force on its date cannot be settled or approved while it has none (refused before the clerk limit is considered).
32	// An OPEN claim (not deferred, not in a closed period) can be split: an amount above 0.00 and below its own goes to a new
33	// OPEN claim with the next number, listed as the person's newest and showing the claim's number as split-from.
34	// A steward can re-date an OPEN or PENDING claim (not to a date after its person's retirement, nor one in a closed
35	// period): its due-by and any statement figure stay, and so its period (that of its due-by) and its number stay too.
36	function ClaimStatusCell({ sheetId, claim }: { sheetId: string; user: string; personId: number; claim: Claim }) {
37	  const [user] = useUser();
38	  const queryClient = useQueryClient();
39	  const [reason, setReason] = useState('');
40	  const [moveTo, setMoveTo] = useState('');
41	  const [deferUntil, setDeferUntil] = useState('');
42	  const [splitAmount, setSplitAmount] = useState('');
43	  const [newDate, setNewDate] = useState('');
44	  const people = usePeople(sheetId);
45	  const [editingId, setEditing] = useEditingClaim();
46	  const periods = usePeriods(sheetId);
47	  const roles = useRoles(sheetId);
48	  // An edit the screen can already tell is refused shows its refusal at once, before any request: the claim form must
49	  // not be taken for its editor. The server refuses the same edits (and any it alone can tell).
50	  const [refused, setRefused] = useState<string>();
51	  // A viewer's edit is refused too, but its editor opens (to be cancelled), as for a lock another user holds.
52	  const viewer = () => (roles.data ?? []).some((r) => r.user === user && r.role === 'viewer');
53	  const refusal = (): string | undefined => {
54	    if (viewer()) return 'A viewer may not change anything on this sheet';
55	    if (claim.status !== 'DRAFT') return 'Only a DRAFT claim can be edited; void it and add a new one instead';
56	    if (periodOn(periods.data ?? [], claim.dueBy)?.closed) return "That claim's date is in a closed period";
57	    return undefined;
58	  };
59	  const base = `/api/sheets/${encodeURIComponent(sheetId)}/claims`;
60	  // Opening the claim's editor takes its lock. A claim that cannot be edited is refused and its editor stays shut; one
61	  // whose lock another user holds (409) is refused too, but its editor opens, to be saved once that user lets it go.
62	  // Opening another claim's editor lets go of the one open before.
63	  const lock = useMutation({
64	    mutationKey: claimLockKey(sheetId),
65	    mutationFn: () => postJson<Claim>(`${base}/${claim.id}/lock`, { by: user ?? '' }),
66	    onSuccess: () => openEditor(),
67	    onError: (e) => {
68	      if (e instanceof HttpError && e.status === 409) openEditor();
69	    },
70	  });
71	  // A save of the claim's open editor is its next action: the lock's refusal goes.
72	  const saving = useIsMutating({ mutationKey: claimSaveKey(sheetId) }) > 0 && editingId === claim.id;
73	  const resetLock = lock.reset;
74	  useEffect(() => {
75	    if (saving) resetLock();
76	  }, [saving, resetLock]);
77	  const openEditor = () => {
78	    if (editingId !== undefined && editingId !== claim.id) unlock(editingId);
79	    setEditing(claim.id);
80	  };
81	  const unlock = (id: number) => {
82	    void postJson(`${base}/${id}/unlock`, { by: user ?? '' }).catch(() => {
83	      // a lock not let go of is dropped when the sheet's today changes
84	    });
85	  };
86	  const change = useMutation({
87	    mutationFn: (to: Change) =>
88	      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/status`, { ...to, by: user ?? '' }),
89	    onSuccess: () => {
90	      setReason('');
91	      return queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) });
92	    },
93	  });
94	  const reassign = useMutation({
95	    mutationFn: (personId: string) => {
96	      if (personId === '') throw new Error('Choose the person to move the claim to');
97	      return putJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/person`,
98	        { personId: Number(personId), by: user ?? '' });
99	    },
100	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
101	  });
102	  // A steward's re-settle of a SETTLED claim at the figure it would have today as an open claim bound by no statement.
103	  const resettle = useMutation({
104	    mutationFn: () =>
105	      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/resettle`, { by: user ?? '' }),
106	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
107	  });
108	  const defer = useMutation({
109	    mutationFn: (until: string) => {
110	      if (until.trim() === '') throw new Error('Enter the date to defer the claim until');
111	      return postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/defer`,
112	        { until: until.trim(), by: user ?? '' });
113	    },
114	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
115	  });
116	  const proof = useMutation({
117	    mutationFn: () =>
118	      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/proof`, { by: user ?? '' }),
119	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
120	  });
121	  const split = useMutation({
122	    mutationFn: (amount: string) =>
123	      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/split`,
124	        { amount: amount.trim(), by: user ?? '' }),
125	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
126	  });
127	  // A steward's re-date of an OPEN or PENDING claim: its due-by and any statement figure stay, and with them its period.
128	  const redate = useMutation({
129	    mutationFn: (date: string) => {
130	      if (date.trim() === '') throw new Error("Enter the claim's new date");
131	      return postJson<Claim>(`/api/sheets/${encodeURIComponent(sheetId)}/claims/${claim.id}/redate`,
132	        { date: date.trim(), by: user ?? '' });
133	    },
134	    onSuccess: () => queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
135	  });
136	  // Each action on the claim clears the other's refusal, so one error shows: the last action's.
137	  const changeTo = (to: Change) => {
138	    reassign.reset();
139	    resettle.reset();
140	    defer.reset();
141	    proof.reset();
142	    split.reset();
143	    redate.reset();
144	    lock.reset();
145	    setRefused(undefined);
146	    change.mutate(to);
147	  };
148	  const resetAll = () => {
149	    change.reset();
150	    reassign.reset();
151	    resettle.reset();
152	    defer.reset();
153	    proof.reset();
154	    split.reset();
155	    redate.reset();
156	    lock.reset();
157	    setRefused(undefined);
158	  };
159	  const busy = lock.isPending || change.isPending || reassign.isPending || resettle.isPending || defer.isPending || proof.isPending || split.isPending
160	    || redate.isPending;
161	  const error = (refused === undefined ? null : new Error(refused)) ?? lock.error ?? change.error ?? reassign.error ?? resettle.error ?? defer.error ?? proof.error ?? split.error ?? redate.error;
162	
163	  return (
164	    <>
165	      <span data-testid="claim-number">{claim.number ?? ''}</span>{' '}
166	      <span data-testid="claim-status">{claim.status}</span>{' '}
167	      <span data-testid="claim-opened-by">{claim.openedBy ?? ''}</span>{' '}
168	      {ACTIONS.map((a) => (
169	        <button
170	          key={a.action}
171	          type="button"
172	          data-testid={`claim-${a.action}`}
173	          disabled={busy}
174	          onClick={() => changeTo(a.change)}
175	        >
176	          {a.label}
177	        </button>
178	      ))}{' '}
179	      <input
180	        data-testid="claim-reject-reason"
181	        placeholder="Reject reason"
182	        value={reason}
183	        onChange={(e) => setReason(e.target.value)}
184	      />
185	      <button
186	        type="button"
187	        data-testid="claim-reject"
188	        disabled={busy}
189	        onClick={() => changeTo({ status: 'OPEN', review: true, reason })}
190	      >
191	        Reject
192	      </button>{' '}
193	      <select data-testid="claim-reassign-to" value={moveTo} onChange={(e) => setMoveTo(e.target.value)}>
194	        <option value="">Move to…</option>
195	        {(people.data ?? []).filter((p) => p.id !== claim.personId).map((p) => (
196	          <option key={p.id} value={String(p.id)}>
197	            {p.name}
198	          </option>
199	        ))}
200	      </select>
201	      <button
202	        type="button"
203	        data-testid="claim-reassign"
204	        disabled={busy}
205	        onClick={() => {
206	          change.reset();
207	          resettle.reset();
208	          defer.reset();
209	          proof.reset();
210	          split.reset();
211	          redate.reset();
212	          lock.reset();
213	          setRefused(undefined);
214	          reassign.mutate(moveTo);
215	        }}
216	      >
217	        Move
218	      </button>{' '}
219	      <button
220	        type="button"
221	        data-testid="claim-resettle"
222	        disabled={busy}
223	        onClick={() => {
224	          change.reset();
225	          reassign.reset();
226	          defer.reset();
227	          proof.reset();
228	          split.reset();
229	          redate.reset();
230	          lock.reset();
231	          setRefused(undefined);
232	          resettle.mutate();
233	        }}
234	      >
235	        Re-settle
236	      </button>{' '}
237	      Deferred <span data-testid="claim-deferred">{claim.deferred ? 'yes' : 'no'}</span>{' '}
238	      <span data-testid="claim-deferred-until">{claim.deferredUntil ?? ''}</span>{' '}
239	      <input
240	        type="date"
241	        data-testid="claim-defer-date"
242	        value={deferUntil}
243	        onChange={(e) => {
244	          setDeferUntil(e.target.value);
245	          defer.reset();
246	        }}
247	      />
248	      <button
249	        type="button"
250	        data-testid="claim-defer"
251	        disabled={busy}
252	        onClick={() => {
253	          change.reset();
254	          reassign.reset();
255	          resettle.reset();
256	          proof.reset();
257	          split.reset();
258	          redate.reset();
259	          lock.reset();
260	          setRefused(undefined);
261	          defer.mutate(deferUntil);
262	        }}
263	      >
264	        Defer
265	      </button>{' '}
266	      Proofs <span data-testid="claim-proofs">{claim.proofs ?? 0}</span>{' '}
267	      <button
268	        type="button"
269	        data-testid="claim-proof"
270	        disabled={busy}
